heroes = {}
with open('extracted_heroes.txt', 'r') as f:
    for line in f:
        parts = line.strip().split(',')
        if len(parts) >= 3:
            hero_id = parts[0]
            height_str = parts[1]
            publisher_str = parts[2]
            try:
                height = float(height_str) if height_str else None
            except:
                height = None
            try:
                publisher_id = int(publisher_str) if publisher_str else None
            except:
                publisher_id = None
            if hero_id not in heroes:
                heroes[hero_id] = {'height': None, 'publisher': None}
            if height is not None:
                heroes[hero_id]['height'] = height
            if publisher_id is not None:
                heroes[hero_id]['publisher'] = publisher_id

total_in_range = 0
marvel_in_range = 0
for hero_id, data in heroes.items():
    height = data['height']
    publisher = data['publisher']
    if height is not None and publisher is not None:
        if 150 <= height <= 180:
            total_in_range += 1
            if publisher == 13:
                marvel_in_range += 1
percentage = (marvel_in_range / total_in_range * 100) if total_in_range > 0 else 0
print(f"Total in range: {total_in_range}, Marvel: {marvel_in_range}, Percentage: {percentage}")

